/**
 * 表示用于装有流体的方块（如炼药锅）中的流体类型。
 */
export enum FluidType {
    /**
     * @remarks
     * 表示一种流体类型：熔岩。
     *
     */
    Lava = 'Lava',
    /**
     * @remarks
     * 表示一种流体类型：药水。
     *
     */
    Potion = 'Potion',
    /**
     * @remarks
     * 表示一种流体类型：细雪。
     *
     */
    PowderSnow = 'PowderSnow',
    /**
     * @remarks
     * 表示一种流体类型：水。
     *
     */
    Water = 'Water',
}